SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;

-- ============================================================================
-- 0438: Expand Domain Pack Evidence Type -> matter linkage data (follows 0437).
--   0437 populated auto-derived RelevanceKeywords (353/353), subtype MatterTypeCodes for 20 types, and 25 rules.
--   This migration widens all three using ONLY codes verified to exist in the active catalog:
--     1) MatterTypeCodes  : +~90 additional subtype-specific evidence types (MVA family, premises, product, med-mal,
--        wrongful death, dog bite, rideshare, trucking, nursing home, construction, TBI/spinal, employment pack).
--        Only rows that are still NULL are set; 0437 assignments are preserved.
--     2) RelevanceKeywords: curated legal/colloquial synonyms APPENDED to the auto-derived list (dedup, 1000 cap)
--        so corpus hits fire on how documents actually talk (e.g. "rear-ended", "T-bone", "ER", "x-ray", "MRI").
--     3) RelevanceRule    : +~75 PRIORITIZE rules - dependency chains (DOCUMENT_PRESENT) and matter-corpus
--        signals (MATTER_SIGNAL). Still no EXCLUDE rules (inclusion gating stays a deliberate per-pack choice).
--   Every rule targets a real EvidenceTypeCode in the same pack and is skipped if already present. Idempotent.
-- ============================================================================
BEGIN TRANSACTION;

DECLARE @Now DATETIME2=SYSUTCDATETIME();
DECLARE @SystemUserId UNIQUEIDENTIFIER='00000000-0000-0000-0000-000000000000';

-- ---------------------------------------------------------------------------
-- 1) Additional MatterTypeCodes (subtype-specific only; still NULL rows only)
-- ---------------------------------------------------------------------------
