	;WITH merged AS
	(
		SELECT e.DecisionDomainPackEvidenceTypeId,
			   STRING_AGG(t.Token,N',') WITHIN GROUP (ORDER BY t.Token) AS Keywords
		FROM POLOXI.Legal_DecisionDomainPackEvidenceType e
		JOIN @Kw k ON k.EvidenceTypeCode=e.EvidenceTypeCode
		CROSS APPLY
		(
			SELECT DISTINCT LOWER(LTRIM(RTRIM(s.value))) AS Token
			FROM STRING_SPLIT(ISNULL(e.RelevanceKeywords,N'')+N','+k.Keywords,N',') s
			WHERE LEN(LTRIM(RTRIM(s.value)))>1
		) t
		WHERE e.IsDeleted=0
		GROUP BY e.DecisionDomainPackEvidenceTypeId
	)
	UPDATE e
	   SET e.RelevanceKeywords=LEFT(m.Keywords,1000),
		   e.ModifiedDateUtc=@Now,
		   e.ModifiedByUserId=@SystemUserId
	  FROM POLOXI.Legal_DecisionDomainPackEvidenceType e
	  JOIN merged m ON m.DecisionDomainPackEvidenceTypeId=e.DecisionDomainPackEvidenceTypeId
	 WHERE ISNULL(e.RelevanceKeywords,N'')<>LEFT(m.Keywords,1000);
END;

-- ---------------------------------------------------------------------------
-- 3) Additional PRIORITIZE rules (dependency chains + matter-corpus signals). Same semantics as 0437.
-- ---------------------------------------------------------------------------
